package com.goldenhour.dispatch.evaluation;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.goldenhour.dispatch.common.ConflictException;
import com.goldenhour.dispatch.routing.CityModel;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.io.InputStream;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicReference;

/**
 * Serves the published evaluation (generated by {@link EvaluationMain}, bundled in the jar) and lets the
 * dashboard re-run a smaller one on demand.
 */
@Service
public class EvaluationService {

    private final CityModel city;
    private final ObjectMapper json;
    private final ExecutorService worker = Executors.newSingleThreadExecutor(r -> {
        Thread t = new Thread(r, "evaluation");
        t.setDaemon(true);
        return t;
    });
    private final AtomicReference<String> status = new AtomicReference<>("IDLE");
    private volatile Object latestRun;

    public EvaluationService(CityModel city, ObjectMapper json) {
        this.city = city;
        this.json = json;
    }

    /** The full published result (5 seeds x 14 days, normal + surge). */
    public JsonNode published() throws IOException {
        try (InputStream in = getClass().getClassLoader().getResourceAsStream("evaluation/evaluation-report.json")) {
            if (in == null) {
                throw new IllegalStateException("evaluation-report.json not bundled");
            }
            return json.readTree(in);
        }
    }

    public record RunStatus(String status, Object result) {
    }

    public RunStatus start(int seeds, int days, double callsPerDay) {
        if (!status.compareAndSet("IDLE", "RUNNING") && !status.compareAndSet("DONE", "RUNNING")) {
            throw new ConflictException("An evaluation is already running");
        }
        worker.submit(() -> {
            try {
                latestRun = new EvaluationRunner(city).run(seeds, days, callsPerDay, 50, true);
                status.set("DONE");
            } catch (RuntimeException e) {
                latestRun = e.getMessage();
                status.set("IDLE");
            }
        });
        return latest();
    }

    public RunStatus latest() {
        return new RunStatus(status.get(), latestRun);
    }
}
